        // IAccessControl interface id as declared in original contract: we compute it by XORing selectors
        // but simplest: construct the set of function selectors declared in IAccessControl and xor them
        // function selectors in IAccessControl: hasRole(bytes32,address), getRoleAdmin(bytes32), grantRole(bytes32,address), revokeRole(bytes32,address), renounceRole(bytes32,address)
        bytes4 s1 = bytes4(keccak256("hasRole(bytes32,address)"));
