        bytes4 s3 = bytes4(keccak256("grantRole(bytes32,address)"));
        bytes4 s4 = bytes4(keccak256("revokeRole(bytes32,address)"));
        bytes4 s5 = bytes4(keccak256("renounceRole(bytes32,address)"));
        bytes4 IACCESS_ID = s1 ^ s2 ^ s3 ^ s4 ^ s5;

        // Call supportsInterface and capture whether it returns/ reverts
        bool ok;
        bool result;
        try c.supportsInterface(interfaceId) returns (bool r) {
            ok = true;
            result = r;
